import numpy as np, collections, json
di=np.array(G['Demo pair 1 input']); do=np.array(G['Demo pair 1 output'])
ti=np.array(G['Test input'])

def solve(g):
    g=np.array(g); H,W=g.shape
    cnt=collections.Counter(g.flatten()); bg=cnt.most_common(1)[0][0]
    pts=[tuple(map(int,p)) for p in np.argwhere(g!=bg)]
    out=g.copy()
    # corner colors keyed by position
    corner={p:g[p] for p in pts}
    # orientation: if corners share a column -> paint rows (demo case); if share a row -> paint columns (test case)
    if len({p[0] for p in pts})==1:
        # paint columns r=0,2,... ; exclude (r==0 and (c+r) odd); corners always painted; color by nearer corner by column distance
        for c in range(W):
            if c%2==1: continue
            for r in range(H):
                if r==0 and (c+r)%2==1: continue
                dL=abs(c-corner[(min(pts,key=lambda q:q[1]))[1]]); dR=abs(c-corner[max(pts,key=lambda q:q[1])][1])
                out[r,c]=corner[(min(pts,key=lambda q:q[1]))[1]] if dL<=dR else corner[max(pts,key=lambda q:q[1])][1]
    else:
        # demo case: paint columns c=0,2,...; exclude (c==0 and (r+c) odd); color by nearer corner by row distance
        for c in range(W):
            if c%2==1: continue
            for r in range(H):
                if c==0 and (r+c)%2==1: continue
                dT=abs(r-corner[min(pts,key=lambda q:q[0])][0]); dB=abs(r-corner[max(pts,key=lambda q:q[0])][0])
                out[r,c]=corner[min(pts,key=lambda q:q[0])][0] if dT<=dB else corner[max(pts,key=lambda q:q[0])][0]
    return out.tolist()

print('demo OK:', np.array_equal(np.array(solve(di)),do))
